import json,sys,math,uuid
from pathlib import Path
sys.path.insert(0,'pcb/tools')
from shapely.geometry import box
import local_router as LR, plan_bottom_sites as PB,plan_series_resistor as PS
PB.W=.15
D=json.load(open('build/mcu-near-usb/resume78-led-damped/geometry-r192.json'))
L=LR.Layout(D);NET='KEY_RGB_CHAIN_29';SRC=NET+'_SRC';REF='R193';LED='LED16'
# Existing pours are regenerated by native KiCad after the edit.
L.cu={k:[c for c in v if c[2]!='zone'] for k,v in L.cu.items()}
p=next(p for p in L.fps[LED]['pads'] if p['num']=='3')
path,stubs=PS.trace(L,LED,NET,p)
print('trace',[(t[2],t[3]) for t in path],flush=True)
# Remove the complete initial run to its last exact endpoint; preserve the downstream branch.
removed=stubs+[t[1] for t in path]
for t in removed:L.remove_track(t)
for c in L.cu['F.Cu']:
 if c[2]=='pad' and c[3][:2]==(LED,'3'):c[1]=SRC
base=PB.snapshot(L)
# Search valid source vias, then require actual front-copper route to the LED pad.
vs=[]
for x in [round(10.5+i*.2,4) for i in range(40)]:
 for y in [round(30+i*.2,4) for i in range(40)]:
  if L.via_ok(x,y,SRC):vs.append((math.hypot(x-p['x'],y-p['y']),x,y))
vs.sort();print('source vias',len(vs),vs[:15],flush=True)
for dist,vx,vy in vs:
 PB.restore(L,base);vi=L.add_via(vx,vy,SRC)
 front=L.route('F.Cu',(vx,vy),SRC,width=.15,half=8,goal_filter=lambda c:c[2]=='pad' and c[3][:2]==(LED,'3'))
 if front is None:continue
 print('reachable source via',vx,vy,flush=True)
 withvia=PB.snapshot(L)
 candidates=[]
 for ix in range(-24,25):
  for iy in range(-24,25):
   x,y=round(vx+ix*.25,4),round(vy+iy*.25,4)
   for rot in (0,90,180,270):candidates.append((math.hypot(x-vx,y-vy),x,y,rot))
 for _,x,y,rot in sorted(candidates):
  PB.restore(L,withvia)
  sx,sy=(.54,.64) if rot in (0,180) else (.64,.54)
  pads={n:(round(x+v[0],4),round(y+v[1],4),sx,sy) for n,v in PS.OFFS[rot].items()}
  court=box(x-.93,y-.47,x+.93,y+.47) if rot in (0,180) else box(x-.47,y-.93,x+.47,y+.93)
  geoms=[box(a-c/2,b-d/2,a+c/2,b+d/2) for a,b,c,d in pads.values()]
  if not PB.bottom_free(L,court,geoms):continue
  # Connect source to the verified source via, and output to existing downstream copper.
  nets={'1':SRC,'2':NET};got=PB.connect(L,REF,pads,nets,8)
  if got is None:continue
  vias,tracks=got
  ops=[{'op':'remove_tracks','tracks':removed},{'op':'set_pad_net','ref':LED,'pad':'3','net':SRC},
  {'op':'add_footprint','ref':REF,'lib_dir':PS.LIB_DIR,'name':'R_0402_1005Metric','fpid':'Maru60:R_0402_1005Metric','side':'B.Cu','x':x,'y':y,'rot':rot,'value':'100 1%','pad_nets':nets,'path':f'/{PS.CORE_SHEET}/{uuid.uuid5(uuid.NAMESPACE_URL,"maru60/order-candidate/"+REF)}','sheetname':'/Core/','sheetfile':'maru60-core.kicad_sch','expect_pads':{n:list(v[:2]) for n,v in pads.items()}},
  {'op':'add_vias','vias':[vi]+vias},{'op':'add_tracks','tracks':front+tracks}]
  out=Path('build/mcu-near-usb/resume79-r193.json');out.write_text(json.dumps({'note':'Series resistor before both LED30 branches; native DRC and actual-route SI required.','ops':ops},indent=2)+'\n')
  print('SUCCESS',x,y,rot,'vias',[vi]+vias,'tracks',len(front+tracks),flush=True);sys.exit(0)
print('NO ROUTE',flush=True);sys.exit(1)
